function small=v4RunTrackAFormalCellR14(root,c,p,algorithmSignature,ci,si)
cases=[-366 0];snrs=-30:-21;caseTime=cases(ci);snrDb=snrs(si);n=20000;codeHash=v4Sha256([v4Sha256(mfilename('fullpath')) v4Sha256(fullfile(root,'src','paper_anchor','v4RunTrackAR14PairedPacket.m'))]);signature=v4Sha256(sprintf('%s|%s|R14|case=%d|snr=%d|N=20000|seed=990000000',algorithmSignature,codeHash,ci,snrDb));folder=fullfile(root,'results','formal','track_a','R14-dual-hypothesis',sprintf('case_%d',ci),sprintf('snr_%+03d',snrDb));if ~isfolder(folder),mkdir(folder);end;checkpoint=fullfile(folder,'checkpoint.mat');final=fullfile(folder,'formal_cell.mat');if isfile(final),x=load(final,'formalCell');if strcmp(x.formalCell.signature,signature),small=rmfield(x.formalCell,'state');return,end;error('V4:R14Signature','Final signature mismatch');end;if isfile(checkpoint),state=v4LoadCheckpoint(checkpoint,signature);else,state=localState(n);end;seed=990000000+(ci-1)*1000000+(si-1)*100000;
for id=state.completed+1:n,x=v4RunTrackAR14PairedPacket(c,caseTime,snrDb,id,seed,p);state.symbolErrors(id,:)=uint8(cellfun(@(z)z.symbolErrors,x.metrics));state.cfoSseBins(id,:)=cellfun(@(z)z.cfoSquaredErrorBins,x.metrics);state.runtimeSec(id,:)=single(x.runtimeSec);for method=1:4,state.detectedLabels(id,method,:)=uint16(x.receivers{method}.detectedPhysicalBins);state.estimatedCfoBins(id,method,:)=single(x.receivers{method}.estimatedCfoBins);end;state.truthLabels(id,:)=uint16(x.truth.labels);state.truthCfoBins(id,:)=single(x.truth.dataCfoHz/c.fftBinSpacingHz);stage=x.receivers{4};state.stageAccepted(id,:)=stage.virtualPilotAccepted;labels=stage.vpUsedLabel;labels(~isfinite(labels))=0;state.stageUsedLabel(id,:)=uint16(labels);state.completed=id;if mod(id,250)==0||id==n,v4WriteCheckpointAtomic(checkpoint,state,signature);fprintf('R14 formal A Case %d SNR %d: %d/20000\n',ci,snrDb,id);end;end
formalCell=struct('caseIndex',ci,'caseStartTimeSec',caseTime,'snrDb',snrDb,'fixedPackets',n,'completedPackets',n,'signature',signature,'algorithmSignature',algorithmSignature,'formalCodeHash',codeHash,'seedRoot',seed,'state',state);save(final,'formalCell','-v7.3');small=rmfield(formalCell,'state');write(fullfile(folder,'formal_cell.json'),jsonencode(small,'PrettyPrint',true));
end
function s=localState(n),s=struct('completed',0,'symbolErrors',zeros(n,4,'uint8'),'cfoSseBins',zeros(n,4),'runtimeSec',zeros(n,4,'single'),'detectedLabels',zeros(n,4,23,'uint16'),'estimatedCfoBins',zeros(n,4,23,'single'),'truthLabels',zeros(n,23,'uint16'),'truthCfoBins',zeros(n,23,'single'),'stageAccepted',false(n,23),'stageUsedLabel',zeros(n,23,'uint16'));end
function write(path,text),f=fopen(path,'w','n','UTF-8');cl=onCleanup(@()fclose(f));fprintf(f,'%s\n',text);clear cl,end
